import (
	"errors"
	"strconv"
	"strings"
	"time"
)

// ParseTimeout parses s as a timeout. s is a non-negative integer number of
// seconds, such as "30", or a Go duration string, such as "500ms" or "2s".
// Surrounding whitespace is ignored. It rejects an empty string and a
// negative number.
func ParseTimeout(s string) (time.Duration, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, errors.New("empty timeout")
	}
	if n, err := strconv.Atoi(s); err == nil {
		if n < 0 {
			return 0, errors.New("negative timeout")
		}
		return time.Duration(n) * time.Second, nil
	}
	d, err := time.ParseDuration(s)
	if err != nil {
		return 0, err
	}
	if d < 0 {
		return 0, errors.New("negative timeout")
	}
	return d, nil
}

