export interface RetryOptions {
  attempts?: number;
  baseMs?: number;
  factor?: number;
  maxMs?: number;
}

export const DEFAULTS: Required<RetryOptions> = {
  attempts: 3,
  baseMs: 200,
  factor: 2,
  maxMs: 5000,
};

export function delayFor(attempt: number, opts: Required<RetryOptions>): number {
  const cap = Math.min(opts.maxMs, opts.baseMs * Math.pow(opts.factor, attempt - 1));
  return Math.random() * cap; // full jitter
}

/**
 * Calls fn until it resolves, then returns its value.
 * Waits a jittered delay between attempts. After the last attempt, throws the
 * error fn threw most recently.
 *
 * @param fn - The function to call. It is called again after each failed attempt.
 * @param opts - Retry options. Each option falls back to its default.
 * @param opts.attempts - Total number of calls to fn. Default: 3.
 * @param opts.baseMs - Delay in milliseconds before the second attempt.
 *   Each later delay scales by `factor`. Default: 200.
 * @param opts.factor - Multiplier applied to the delay after each attempt.
 *   Default: 2.
 * @param opts.maxMs - Upper bound in milliseconds for a single delay.
 *   Default: 5000.
 */
export async function retry<T>(fn: () => Promise<T>, opts: RetryOptions = {}): Promise<T> {
  const o = { ...DEFAULTS, ...opts };
  let last: unknown;
  for (let attempt = 1; attempt <= o.attempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      last = err;
      if (attempt < o.attempts) {
        await new Promise((r) => setTimeout(r, delayFor(attempt, o)));
      }
    }
  }
  throw last;
}

